layers.vertex:
attribute vec3 aVertexPosition;
attribute vec2 aTextureCoord;
uniform mat4 uModelMatrix;
uniform mat4 uViewMatrix;
uniform mat4 uProjectionMatrix;
varying float vDepth;
varying vec3 vWorldPos;
varying vec2 vFixtureCenter;

void main(void) {
  vec4 world = uModelMatrix * vec4(aVertexPosition, 1.0);
  vec4 v = uViewMatrix * world;
  vDepth = -v.z;
  vWorldPos = world.xyz;
  vFixtureCenter = aTextureCoord;
  gl_Position = uProjectionMatrix * v;
}

layers.fragment:
precision mediump float;
uniform vec3 uMaterialDiffuse;
uniform float uTime;
uniform int uHasFog;
uniform vec3 uFogColor;
uniform float uFogNear;
uniform float uFogFar;
varying float vDepth;
varying vec3 vWorldPos;
varying vec2 vFixtureCenter;

void main(void) {
  if (uHasFog == 1 && vDepth >= uFogFar)
    discard;
  float t = clamp((62.6 - vWorldPos.y) / 52.6, 0.0, 1.0);
  float topSoft = smoothstep(0.0, 0.06, t);
  float vFade = topSoft * (1.0 - t) * (1.0 - t) * (1.0 - t * 0.45);

  vec2 rel = vWorldPos.xz - vFixtureCenter;
  vec2 span = mix(vec2(22.0, 6.0), vec2(38.0, 20.0), t);
  vec2 q = rel / span;
  float xFade = 1.0 - smoothstep(0.12, 1.0, abs(q.x));
  float zFade = 1.0 - smoothstep(0.05, 1.0, abs(q.y));
  float hFade = xFade * xFade * zFade;

  // four soft fanned shafts matching the four louver bays of the ceiling fixture, diffusing as they descend
  float bay = 0.5 + 0.5 * cos(q.x * 12.56637);
  float shafts = mix(0.52 + 0.48 * bay * bay, 1.0, t * 0.72);

  float seed = fract(sin(dot(vFixtureCenter, vec2(12.9898, 78.233))) * 43758.5453);
  float hum = 1.0;
  if (seed < 0.2) {
    float wave = sin(uTime * 19.0 + seed * 31.4) * sin(uTime * 43.0 + seed * 53.4);
    hum = wave < -0.68 ? 0.64 : 0.96 + 0.04 * wave;
  }

  float nearFade = smoothstep(10.0, 34.0, vDepth);
  float fogFade = uHasFog == 1 ? 1.0 - clamp((vDepth - uFogNear) / (uFogFar - uFogNear), 0.0, 1.0) : 1.0;
  float alpha = vFade * hFade * shafts * hum * nearFade * fogFade * 0.075;
  if (alpha <= 0.001)
    discard;
  gl_FragColor = vec4(uMaterialDiffuse * alpha, 0.0);
}

layers.vertex:
attribute vec3 aVertexPosition;
attribute vec2 aTextureCoord;
uniform mat4 uModelMatrix;
uniform mat4 uViewMatrix;
uniform mat4 uProjectionMatrix;
varying float vDepth;
varying vec2 vTextureCoord;
varying vec3 vWorldPos;

void main(void) {
  vec4 world = uModelMatrix * vec4(aVertexPosition, 1.0);
  vec4 v = uViewMatrix * world;
  vDepth = -v.z;
  v.z += 1.2 + vDepth * 0.01;
  vTextureCoord = aTextureCoord;
  vWorldPos = world.xyz;
  gl_Position = uProjectionMatrix * v;
}

layers.fragment:
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform sampler2D uSampler;
uniform vec3 uMaterialDiffuse;
uniform int uHasFog;
uniform vec3 uFogColor;
uniform float uFogNear;
uniform float uFogFar;
varying float vDepth;
varying vec2 vTextureCoord;
varying vec3 vWorldPos;

const vec3 GIRDER_STEEL = vec3(0.0824, 0.1059, 0.1529);
const vec3 OXIDE_STAIN = vec3(0.1098, 0.0784, 0.0627);
const vec3 OXIDE_PIT = vec3(0.0667, 0.0314, 0.0196);
const vec3 OXIDE_DARK = vec3(0.1569, 0.0745, 0.0412);
const vec3 OXIDE_MID = vec3(0.3059, 0.1333, 0.0588);
const vec3 OXIDE_WARM = vec3(0.4667, 0.2078, 0.0784);
const vec3 OXIDE_OCHRE = vec3(0.5765, 0.2784, 0.1020);

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float v = noise(p) * 0.54;
  p = vec2(p.x * 1.62 - p.y * 1.21, p.x * 1.21 + p.y * 1.62) + vec2(17.3, 9.7);
  v += noise(p) * 0.31;
  p = vec2(p.x * 1.58 + p.y * 1.26, -p.x * 1.26 + p.y * 1.58) + vec2(31.1, 23.4);
  v += noise(p) * 0.15;
  return v;
}

uniform int uNbLights;
uniform vec3 uAmbientLight;
uniform vec3 uLightPosition[8];
uniform vec3 uLightDiffuse[8];
uniform vec3 uLightAttenuation[8];

vec3 surfaceLight(vec3 worldPos, float emissive) {
  if (uNbLights <= 0)
    return vec3(1.0);
  vec3 total = uAmbientLight;
  for (int i = 0; i < 8; i++) {
    if (i >= uNbLights)
      break;
    vec3 diff = uLightDiffuse[i];
    if (diff.x + diff.y + diff.z <= 0.001)
      continue;
    vec3 delta = uLightPosition[i] - worldPos;
    if (delta.x * delta.x + delta.z * delta.z > 160000.0)
      continue;
    float isCeilingFixture = step(54.0, uLightPosition[i].y);
    float onCeiling = step(58.0, worldPos.y) * isCeilingFixture;
    float verticalSpan = mix(delta.y, 62.0, onCeiling);
    vec3 lightVec = vec3(delta.x, verticalSpan, delta.z);
    float distSq = dot(lightVec, lightVec);
    if (distSq > 160000.0)
      continue;
    vec3 att = uLightAttenuation[i];
    if (att.z > 0.001 && distSq >= 18225.0)
      continue;
    float dist = sqrt(distSq);
    float shortRange = step(0.001, att.z);
    float rangeCutoff = mix(1.0, 1.0 - smoothstep(75.0, 135.0, dist), shortRange);
    float attenuation = rangeCutoff / max(att.x + att.y * dist + att.z * distSq, 0.0001);
    float downward = clamp((uLightPosition[i].y - worldPos.y) / max(dist, 1.0), 0.0, 1.0);
    float spread = mix(1.05, 0.5 + 0.75 * downward * downward, isCeilingFixture);
    total += diff * (attenuation * spread);
  }
  return mix(min(total, vec3(2.5)), max(total, vec3(1.35)), clamp(emissive, 0.0, 1.0));
}

void main(void) {
  vec4 texel = texture2D(uSampler, vTextureCoord);
  if (texel.a < 0.5)
    discard;
  if (uHasFog == 1 && vDepth >= uFogFar) {
    gl_FragColor = vec4(uFogColor, 0.5);
    return;
  }
  vec3 base = texel.rgb;
  float cyanGlow = smoothstep(0.08, 0.25, max(base.b, base.g) - base.r);
  float amberGlow = smoothstep(0.18, 0.42, base.r - base.b) * smoothstep(0.28, 0.55, base.g);
  float lit = clamp(max(cyanGlow, amberGlow * 0.75), 0.0, 1.0);
  float isCeiling = step(58.0, vWorldPos.y);
  vec2 tileUv = fract(vWorldPos.xz / 64.0);
  vec2 borderDist = min(tileUv, 1.0 - tileUv);
  float minBorder = min(borderDist.x, borderDist.y);
  float edgeGirder = 1.0 - smoothstep(0.0, 0.11, minBorder);
  float recessWell = smoothstep(0.14, 0.34, minBorder);
  vec3 overheadTint = mix(vec3(0.88, 0.94, 1.04), vec3(0.68, 0.75, 0.88), recessWell * (1.0 - lit));
  vec3 ceilingColor = base * overheadTint * (1.0 - edgeGirder * 0.22 * (1.0 - lit));
  if (isCeiling > 0.5 && lit < 0.92 && base.b >= base.r - 0.03) {
    vec2 p = vec2(vWorldPos.x * 1.03 + vWorldPos.z * 0.07, vWorldPos.z * 0.97 - vWorldPos.x * 0.07);
    float scale = 21.0;
    vec2 texelPos = floor(p * 4.0) * 0.25;
    float g1 = noise(texelPos / 2.1 + 15.0);
    float g2 = noise(texelPos / 0.85 + 47.0);
    float grain = g1 * 0.52 + g2 * 0.48;
    vec2 jitter = vec2(
      noise(p / 3.8 + vec2(19.3, 7.1)) - 0.5,
      noise(p / 3.8 + vec2(37.9, 23.4)) - 0.5
    ) * 2.1 + vec2(g1 - 0.5, g2 - 0.5) * 0.9;
    vec2 pw = p + jitter;
    float coarse = fbm(pw / scale + 31.0);
    float fineA = noise(vec2(pw.x / (scale * 0.38) - pw.y / (scale * 0.51) + 13.0, pw.y / (scale * 0.38) + pw.x / (scale * 0.51) + 41.0));
    float fineB = 1.0 - abs(noise(vec2(pw.x / (scale * 0.21) + pw.y / (scale * 0.29) + 59.0, pw.y / (scale * 0.21) - pw.x / (scale * 0.29) + 89.0)) * 2.0 - 1.0);
    float spots = coarse * 0.40 + fineA * 0.30 + fineB * 0.18 + grain * 0.12;
    if (spots > 0.49) {
      float thresh = 0.64;
      float patchGate = smoothstep(thresh - 0.06, thresh + 0.03, spots);
      float cofferLip = 1.0 - smoothstep(0.0, 0.038, abs(minBorder - 0.125));
      float cornerPocket = (1.0 - smoothstep(0.0, 0.18, borderDist.x)) * (1.0 - smoothstep(0.0, 0.18, borderDist.y));
      float baseLum = dot(base, vec3(0.299, 0.587, 0.114));
      float crevice = clamp((0.115 - baseLum) * 6.0, 0.0, 1.0);
      float ridge = clamp((baseLum - 0.13) * 4.5, 0.0, 1.0);
      float seamBoost = (edgeGirder * 0.16 + cofferLip * 0.18 + cornerPocket * 0.18 + crevice * 0.12) * smoothstep(0.45, 0.78, fineA * 0.60 + grain * 0.40);
      float area = smoothstep(thresh, thresh + 0.10, spots + crevice * 0.03 * patchGate - ridge * 0.04);
      area = clamp(area + seamBoost * 0.65 * patchGate, 0.0, 1.0);
      float near = 1.0 - smoothstep(220.0, 640.0, vDepth);
      float bump = 0.0;
      if (near > 0.01 && area > 0.08) {
        float gShift = noise((texelPos + vec2(0.25, -0.25)) / 1.15 + 47.0);
        bump = (g2 - gShift) * near;
      }
      float edgeBreak = smoothstep(0.26, 0.74, grain * 0.58 + fineB * 0.42);
      float breakup = mix(0.62 * edgeBreak, (0.20 + grain * 0.94 + crevice * 0.18 - ridge * 0.16) * (0.40 + 0.60 * edgeBreak), near);
      float amount = clamp(area * breakup * 1.22 * (1.0 - lit), 0.0, 1.0);
      float stain = smoothstep(0.08, 0.31, amount * 0.75 + area * edgeBreak * 0.25) * (1.0 - lit);
      float flake = smoothstep(0.65, 0.90, grain) * smoothstep(0.50, 0.84, amount) * near;
      float pit = smoothstep(0.39, 0.15, grain) * smoothstep(0.68, 0.94, amount + crevice * 0.22) * near;
      if (stain > 0.01) {
        vec3 steelDetail = ceilingColor - GIRDER_STEEL;
        vec3 stained = clamp(mix(GIRDER_STEEL, OXIDE_STAIN, 0.56) + steelDetail * 0.84, 0.0, 1.0);
        ceilingColor = mix(ceilingColor, stained, stain * 0.27);
        if (amount > 0.16) {
          vec3 oxide = mix(OXIDE_DARK, OXIDE_MID, smoothstep(0.22, 0.62, amount));
          oxide = mix(oxide, OXIDE_WARM, smoothstep(0.58, 0.90, amount));
          oxide = mix(oxide, OXIDE_OCHRE, flake * 0.62);
          oxide = mix(oxide, OXIDE_PIT, pit * 0.76);
          float relief = bump * (0.07 + 0.07 * amount);
          float keepSteel = mix(0.74, 0.28, smoothstep(0.20, 0.88, amount));
          vec3 corroded = clamp(oxide + steelDetail * keepSteel + vec3(1.0, 0.58, 0.28) * relief, 0.0, 1.0);
          float rustBlend = smoothstep(0.16, 0.42, amount) * clamp(0.32 + amount * 0.58, 0.0, 1.0);
          ceilingColor = mix(ceilingColor, corroded, rustBlend);
        }
      }
    }
  }
  vec3 color = mix(base, ceilingColor, isCeiling);
  color *= uMaterialDiffuse * surfaceLight(vWorldPos, lit);
  color += vec3(0.04, 0.18, 0.24) * cyanGlow * (1.0 - isCeiling) * 0.45;
  float pitDepthFade = smoothstep(-2.0, -48.0, vWorldPos.y);
  vec3 pitFogColor = uHasFog == 1 ? uFogColor * 0.42 : vec3(0.02, 0.03, 0.06);
  color = mix(color, pitFogColor, pitDepthFade);
  if (uHasFog == 1) {
    float fade = clamp((vDepth - uFogNear) / (uFogFar - uFogNear), 0.0, 1.0);
    color = mix(color, uFogColor, fade);
  }
  gl_FragColor = vec4(color, 0.5);
}

layers.vertex:
attribute vec3 aVertexPosition;
attribute vec2 aTextureCoord;
uniform mat4 uModelMatrix;
uniform mat4 uViewMatrix;
uniform mat4 uProjectionMatrix;
varying float vDepth;
varying float vHeight;
varying vec2 vTextureCoord;
varying vec2 vWorld;
varying vec2 vSurface;
varying vec3 vWorldPos;

void main(void) {
  vec4 world = uModelMatrix * vec4(aVertexPosition, 1.0);
  vec4 v = uViewMatrix * world;
  vDepth = -v.z;
  vHeight = world.y;
  vTextureCoord = aTextureCoord;
  vWorld = world.xz;
  vSurface = vec2(aVertexPosition.x + aVertexPosition.z, aVertexPosition.y) + uModelMatrix[3].xz * 0.37;
  vWorldPos = world.xyz;
  vec4 clip = uProjectionMatrix * v;
  clip.z -= 0.00001 * clip.w;
  gl_Position = clip;
}

layers.fragment:
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform sampler2D uSampler;
uniform vec3 uMaterialDiffuse;
uniform int uHasFog;
uniform vec3 uFogColor;
uniform float uFogNear;
uniform float uFogFar;
varying float vDepth;
varying float vHeight;
varying vec2 vTextureCoord;
varying vec2 vWorld;
varying vec2 vSurface;
varying vec3 vWorldPos;


const vec3 STEEL = vec3(0.0824, 0.1059, 0.1529);
const vec3 RUST_STAIN = vec3(0.1180, 0.0820, 0.0640);
const vec3 RUST_PIT = vec3(0.0745, 0.0353, 0.0216);
const vec3 RUST_DARK = vec3(0.1647, 0.0784, 0.0431);
const vec3 RUST = vec3(0.3216, 0.1412, 0.0627);
const vec3 RUST_BRIGHT = vec3(0.4941, 0.2196, 0.0824);
const vec3 RUST_OCHRE = vec3(0.6039, 0.2941, 0.1059);

float hash3(vec3 p) {
  p = fract(p * 0.1031);
  p += dot(p, p.yzx + 33.33);
  return fract((p.x + p.y) * p.z);
}

float noise3(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  vec3 u = f * f * (3.0 - 2.0 * f);
  float n00 = mix(hash3(i), hash3(i + vec3(1.0, 0.0, 0.0)), u.x);
  float n10 = mix(hash3(i + vec3(0.0, 1.0, 0.0)), hash3(i + vec3(1.0, 1.0, 0.0)), u.x);
  float n01 = mix(hash3(i + vec3(0.0, 0.0, 1.0)), hash3(i + vec3(1.0, 0.0, 1.0)), u.x);
  float n11 = mix(hash3(i + vec3(0.0, 1.0, 1.0)), hash3(i + vec3(1.0, 1.0, 1.0)), u.x);
  return mix(mix(n00, n10, u.y), mix(n01, n11, u.y), u.z);
}

float fbm3(vec3 p) {
  float v = noise3(p) * 0.54;
  p = vec3(p.x * 1.62 - p.y * 1.21 + 17.3, p.x * 1.21 + p.y * 1.62 - p.z * 0.64 + 9.7, p.z * 1.78 + p.y * 0.64 + 23.4);
  v += noise3(p) * 0.31;
  p = vec3(p.x * 1.58 + p.z * 1.26 + 31.1, p.y * 1.71 - p.x * 0.58 + 15.8, -p.x * 1.26 + p.z * 1.58 + 41.2);
  v += noise3(p) * 0.15;
  return v;
}


uniform int uNbLights;
uniform vec3 uAmbientLight;
uniform vec3 uLightPosition[8];
uniform vec3 uLightDiffuse[8];
uniform vec3 uLightAttenuation[8];

vec3 surfaceLight(vec3 worldPos, float emissive) {
  if (uNbLights <= 0)
    return vec3(1.0);
  vec3 total = uAmbientLight;
  for (int i = 0; i < 8; i++) {
    if (i >= uNbLights)
      break;
    vec3 diff = uLightDiffuse[i];
    if (diff.x + diff.y + diff.z <= 0.001)
      continue;
    vec3 delta = uLightPosition[i] - worldPos;
    if (delta.x * delta.x + delta.z * delta.z > 160000.0)
      continue;
    float isCeilingFixture = step(54.0, uLightPosition[i].y);
    float onCeiling = step(58.0, worldPos.y) * isCeilingFixture;
    float verticalSpan = mix(delta.y, 62.0, onCeiling);
    vec3 lightVec = vec3(delta.x, verticalSpan, delta.z);
    float distSq = dot(lightVec, lightVec);
    if (distSq > 160000.0)
      continue;
    vec3 att = uLightAttenuation[i];
    if (att.z > 0.001 && distSq >= 18225.0)
      continue;
    float dist = sqrt(distSq);
    float shortRange = step(0.001, att.z);
    float rangeCutoff = mix(1.0, 1.0 - smoothstep(75.0, 135.0, dist), shortRange);
    float attenuation = rangeCutoff / max(att.x + att.y * dist + att.z * distSq, 0.0001);
    float downward = clamp((uLightPosition[i].y - worldPos.y) / max(dist, 1.0), 0.0, 1.0);
    float spread = mix(1.05, 0.5 + 0.75 * downward * downward, isCeilingFixture);
    total += diff * (attenuation * spread);
  }
  return mix(min(total, vec3(2.5)), max(total, vec3(1.35)), clamp(emissive, 0.0, 1.0));
}

void main(void) {
  float isDoor = step(0.5, abs(vSurface.x - (vWorld.x + vWorld.y)));
  float isFloor = step(vHeight, -0.15) * (1.0 - isDoor);
  float isCeiling = step(58.0, vHeight) * (1.0 - isDoor);
  float isVertical = (1.0 - isFloor) * (1.0 - isCeiling);
  if (vHeight < -0.21)
    discard;
  if (isDoor > 0.5)
    if (vHeight < -0.01)
      discard;
  if (uHasFog == 1 && vDepth >= uFogFar) {
    gl_FragColor = vec4(uFogColor, 0.5);
    return;
  }
  vec3 steel = texture2D(uSampler, vTextureCoord).rgb;
  vec3 color = steel;
  float cyanGlow = max(steel.b, steel.g) - steel.r;
  float hazardStripe = smoothstep(0.18, 0.38, steel.r - steel.b) * smoothstep(0.24, 0.45, steel.g);
  float lit = smoothstep(0.06, 0.2, cyanGlow);
  float protect = clamp(max(lit, hazardStripe * 0.65), 0.0, 1.0);
  float steelLum = dot(steel, vec3(0.299, 0.587, 0.114));
  float baseLum = dot(STEEL, vec3(0.299, 0.587, 0.114));
  float crevice = clamp((baseLum - steelLum) * 6.5, 0.0, 1.0);
  float ridge = clamp((steelLum - baseLum) * 4.5, 0.0, 1.0);
  float amount = 0.0;
  float stain = 0.0;
  float pit = 0.0;
  float flake = 0.0;
  float bump = 0.0;
  if (lit < 0.95) {
    vec3 worldCoord = vec3(vWorld.x, vHeight, vWorld.y);
    vec3 doorCoord = vec3(vSurface.x * 1.17, vSurface.y, 19.7);
    vec3 pos = mix(worldCoord, doorCoord, isDoor);
    float scale = mix(mix(19.0, 15.5, isDoor), 21.0, isFloor);
    vec3 texel = floor(pos * 4.0) * 0.25;
    float g1 = noise3(texel / 2.1 + vec3(11.0, 17.0, 23.0));
    float g2 = noise3(texel / 0.85 + vec3(40.0, 53.0, 67.0));
    float grain = g1 * 0.52 + g2 * 0.48;
    vec3 jitter = vec3(
      noise3(pos / 3.8 + vec3(13.7, 29.1, 7.3)) - 0.5,
      noise3(pos / 3.8 + vec3(41.3, 7.9, 19.7)) - 0.5,
      noise3(pos / 3.8 + vec3(23.1, 51.7, 37.9)) - 0.5
    ) * 2.1 + vec3(g1 - 0.5, g2 - 0.5, (g1 - g2) * 0.7) * 0.9;
    vec3 pw = pos + jitter;
    float coarse = fbm3(pw / scale + vec3(21.0, 13.0, 37.0));
    float fineA = noise3(vec3(
      pw.x / (scale * 0.38) - pw.y / (scale * 0.51) + 9.0,
      pw.y / (scale * 0.38) + pw.z / (scale * 0.51) + 33.0,
      pw.z / (scale * 0.38) - pw.x / (scale * 0.51) + 57.0
    ));
    float fineB = 1.0 - abs(noise3(vec3(
      pw.x / (scale * 0.21) + pw.y / (scale * 0.29) + 51.0,
      pw.y / (scale * 0.21) - pw.z / (scale * 0.29) + 83.0,
      pw.z / (scale * 0.21) + pw.x / (scale * 0.29) + 19.0
    )) * 2.0 - 1.0);
    float drip = isVertical * (
      noise3(vec3(pw.x * 0.48 + 7.1, pw.y * 0.085 + 19.3, pw.z * 0.48 + 31.7)) * 0.58 +
      noise3(vec3(pw.x * 1.05 + 43.7, pw.y * 0.14 + 61.9, pw.z * 1.05 + 13.5)) * 0.42
    );
    float spots = mix(
      coarse * 0.40 + fineA * 0.30 + fineB * 0.18 + grain * 0.12,
      coarse * 0.36 + fineA * 0.27 + fineB * 0.16 + drip * 0.10 + grain * 0.11,
      isVertical
    );
    if (spots > 0.48) {
      float thresh = mix(mix(0.62, 0.60, isDoor), 0.60, isFloor);
      float patchGate = smoothstep(thresh - 0.06, thresh + 0.03, spots);
      vec3 seam32 = abs(fract((pos + jitter * 0.3) / 32.0) - 0.5);
      vec3 seam64 = abs(fract((pos + jitter * 0.2) / 64.0) - 0.5);
      float seamMask = smoothstep(0.42, 0.76, fineA * 0.58 + grain * 0.42);
      float nearSeam = mix(
        smoothstep(0.45, 0.5, max(seam64.x, seam64.z)) * 0.45,
        smoothstep(0.44, 0.5, max(seam32.x, seam32.z)) * 0.40 + smoothstep(0.45, 0.5, max(seam64.x, seam64.z)) * 0.60,
        isFloor
      ) * seamMask;
      float wallBand = isVertical * (1.0 - smoothstep(0.0, 5.5, max(vHeight, 0.0))) * 0.16 * seamMask * smoothstep(0.45, 0.80, drip);
      float area = smoothstep(thresh, thresh + 0.10, spots + crevice * 0.04 * patchGate - ridge * 0.04);
      area = clamp(area + (nearSeam * 0.16 + wallBand + crevice * 0.08) * patchGate, 0.0, 1.0);
      float near = 1.0 - smoothstep(220.0, 640.0, vDepth);
      if (near > 0.01 && area > 0.08) {
        float gShift = noise3((texel + vec3(0.25, -0.25, 0.25)) / 1.15 + vec3(40.0, 53.0, 67.0));
        bump = (g2 - gShift) * near;
      }
      float edgeBreak = smoothstep(0.26, 0.74, grain * 0.58 + fineB * 0.42);
      float breakup = mix(0.62 * edgeBreak, (0.20 + grain * 0.94 + crevice * 0.18 - ridge * 0.16) * (0.40 + 0.60 * edgeBreak), near);
      amount = clamp(area * breakup * 1.22 * (1.0 - protect), 0.0, 1.0);
      stain = smoothstep(0.08, 0.30, amount * 0.75 + area * edgeBreak * 0.25) * (1.0 - protect);
      flake = smoothstep(0.65, 0.90, grain) * smoothstep(0.48, 0.82, amount) * near;
      pit = smoothstep(0.39, 0.15, grain) * smoothstep(0.67, 0.93, amount + crevice * 0.21) * near;
    }
  }

  if (stain > 0.01) {
    vec3 steelDetail = steel - STEEL;
    vec3 stainedSteel = clamp(mix(STEEL, RUST_STAIN, 0.56) + steelDetail * 0.84, 0.0, 1.0);
    color = mix(steel, stainedSteel, stain * 0.28);
    if (amount > 0.14) {
      float tideRing = isFloor * smoothstep(0.16, 0.31, amount) * (1.0 - smoothstep(0.31, 0.50, amount));
      vec3 oxide = mix(RUST_DARK, RUST, smoothstep(0.22, 0.62, amount));
      oxide = mix(oxide, RUST_BRIGHT, smoothstep(0.58, 0.90, amount));
      oxide = mix(oxide, RUST_OCHRE, flake * 0.65);
      oxide = mix(oxide, RUST_PIT, clamp(pit * 0.78 + tideRing * 0.29, 0.0, 1.0));
      float relief = bump * (0.08 + 0.07 * amount);
      float keepSteel = mix(0.75, 0.27, smoothstep(0.20, 0.88, amount));
      vec3 corroded = clamp(oxide + steelDetail * keepSteel + vec3(1.0, 0.58, 0.28) * relief, 0.0, 1.0);
      float rustBlend = smoothstep(0.14, 0.38, amount) * clamp(0.34 + amount * 0.62 + tideRing * 0.14, 0.0, 1.0);
      color = mix(color, corroded, rustBlend);
    }
  }
  color *= uMaterialDiffuse * surfaceLight(vWorldPos, lit);
  if (uHasFog == 1) {
    float fade = clamp((vDepth - uFogNear) / (uFogFar - uFogNear), 0.0, 1.0);
    color = mix(color, uFogColor, fade);
  }
  gl_FragColor = vec4(color, 0.5);
}

layers.vertex:
attribute vec3 aVertexPosition;
attribute vec2 aTextureCoord;
uniform mat4 uModelMatrix;
uniform mat4 uViewMatrix;
uniform mat4 uProjectionMatrix;
varying float vDepth;
varying float vHeight;
varying vec2 vTextureCoord;
varying vec2 vWorld;
varying vec2 vSurface;
varying vec3 vWorldPos;

void main(void) {
  vec4 world = uModelMatrix * vec4(aVertexPosition, 1.0);
  vec4 v = uViewMatrix * world;
  vDepth = -v.z;
  vHeight = world.y;
  vTextureCoord = aTextureCoord;
  vWorld = world.xz;
  vSurface = vec2(aVertexPosition.x + aVertexPosition.z, aVertexPosition.y) + uModelMatrix[3].xz * 0.37;
  vWorldPos = world.xyz;
  vec4 clip = uProjectionMatrix * v;
  clip.z -= 0.00001 * clip.w;
  gl_Position = clip;
}

layers.fragment:
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform sampler2D uSampler;
uniform vec3 uMaterialDiffuse;
uniform int uHasFog;
uniform vec3 uFogColor;
uniform float uFogNear;
uniform float uFogFar;
varying float vDepth;
varying float vHeight;
varying vec2 vTextureCoord;
varying vec2 vWorld;
varying vec2 vSurface;
varying vec3 vWorldPos;


const vec3 STEEL = vec3(0.0824, 0.1059, 0.1529);
const vec3 RUST_STAIN = vec3(0.1180, 0.0820, 0.0640);
const vec3 RUST_PIT = vec3(0.0745, 0.0353, 0.0216);
const vec3 RUST_DARK = vec3(0.1647, 0.0784, 0.0431);
const vec3 RUST = vec3(0.3216, 0.1412, 0.0627);
const vec3 RUST_BRIGHT = vec3(0.4941, 0.2196, 0.0824);
const vec3 RUST_OCHRE = vec3(0.6039, 0.2941, 0.1059);

float hash3(vec3 p) {
  p = fract(p * 0.1031);
  p += dot(p, p.yzx + 33.33);
  return fract((p.x + p.y) * p.z);
}

float noise3(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  vec3 u = f * f * (3.0 - 2.0 * f);
  float n00 = mix(hash3(i), hash3(i + vec3(1.0, 0.0, 0.0)), u.x);
  float n10 = mix(hash3(i + vec3(0.0, 1.0, 0.0)), hash3(i + vec3(1.0, 1.0, 0.0)), u.x);
  float n01 = mix(hash3(i + vec3(0.0, 0.0, 1.0)), hash3(i + vec3(1.0, 0.0, 1.0)), u.x);
  float n11 = mix(hash3(i + vec3(0.0, 1.0, 1.0)), hash3(i + vec3(1.0, 1.0, 1.0)), u.x);
  return mix(mix(n00, n10, u.y), mix(n01, n11, u.y), u.z);
}

float fbm3(vec3 p) {
  float v = noise3(p) * 0.54;
  p = vec3(p.x * 1.62 - p.y * 1.21 + 17.3, p.x * 1.21 + p.y * 1.62 - p.z * 0.64 + 9.7, p.z * 1.78 + p.y * 0.64 + 23.4);
  v += noise3(p) * 0.31;
  p = vec3(p.x * 1.58 + p.z * 1.26 + 31.1, p.y * 1.71 - p.x * 0.58 + 15.8, -p.x * 1.26 + p.z * 1.58 + 41.2);
  v += noise3(p) * 0.15;
  return v;
}


uniform int uNbLights;
uniform vec3 uAmbientLight;
uniform vec3 uLightPosition[8];
uniform vec3 uLightDiffuse[8];
uniform vec3 uLightAttenuation[8];

vec3 surfaceLight(vec3 worldPos, float emissive) {
  if (uNbLights <= 0)
    return vec3(1.0);
  vec3 total = uAmbientLight;
  for (int i = 0; i < 8; i++) {
    if (i >= uNbLights)
      break;
    vec3 diff = uLightDiffuse[i];
    if (diff.x + diff.y + diff.z <= 0.001)
      continue;
    vec3 delta = uLightPosition[i] - worldPos;
    if (delta.x * delta.x + delta.z * delta.z > 160000.0)
      continue;
    float isCeilingFixture = step(54.0, uLightPosition[i].y);
    float onCeiling = step(58.0, worldPos.y) * isCeilingFixture;
    float verticalSpan = mix(delta.y, 62.0, onCeiling);
    vec3 lightVec = vec3(delta.x, verticalSpan, delta.z);
    float distSq = dot(lightVec, lightVec);
    if (distSq > 160000.0)
      continue;
    vec3 att = uLightAttenuation[i];
    if (att.z > 0.001 && distSq >= 18225.0)
      continue;
    float dist = sqrt(distSq);
    float shortRange = step(0.001, att.z);
    float rangeCutoff = mix(1.0, 1.0 - smoothstep(75.0, 135.0, dist), shortRange);
    float attenuation = rangeCutoff / max(att.x + att.y * dist + att.z * distSq, 0.0001);
    float downward = clamp((uLightPosition[i].y - worldPos.y) / max(dist, 1.0), 0.0, 1.0);
    float spread = mix(1.05, 0.5 + 0.75 * downward * downward, isCeilingFixture);
    total += diff * (attenuation * spread);
  }
  return mix(min(total, vec3(2.5)), max(total, vec3(1.35)), clamp(emissive, 0.0, 1.0));
}

void main(void) {
  float isDoor = step(0.5, abs(vSurface.x - (vWorld.x + vWorld.y)));
  float isFloor = step(vHeight, -0.15) * (1.0 - isDoor);
  float isCeiling = step(58.0, vHeight) * (1.0 - isDoor);
  float isVertical = (1.0 - isFloor) * (1.0 - isCeiling);
  if (vHeight < -0.21)
    discard;
  if (isDoor > 0.5)
    if (vHeight < -0.01)
      discard;
  if (uHasFog == 1 && vDepth >= uFogFar) {
    gl_FragColor = vec4(uFogColor, 0.5);
    return;
  }
  vec3 steel = texture2D(uSampler, vTextureCoord).rgb;
  vec3 color = steel;
  float cyanGlow = max(steel.b, steel.g) - steel.r;
  float hazardStripe = smoothstep(0.18, 0.38, steel.r - steel.b) * smoothstep(0.24, 0.45, steel.g);
  float lit = smoothstep(0.06, 0.2, cyanGlow);
  float protect = clamp(max(lit, hazardStripe * 0.65), 0.0, 1.0);
  float steelLum = dot(steel, vec3(0.299, 0.587, 0.114));
  float baseLum = dot(STEEL, vec3(0.299, 0.587, 0.114));
  float crevice = clamp((baseLum - steelLum) * 6.5, 0.0, 1.0);
  float ridge = clamp((steelLum - baseLum) * 4.5, 0.0, 1.0);
  float amount = 0.0;
  float stain = 0.0;
  float pit = 0.0;
  float flake = 0.0;
  float bump = 0.0;
  if (lit < 0.95) {
    vec3 worldCoord = vec3(vWorld.x, vHeight, vWorld.y);
    vec3 doorCoord = vec3(vSurface.x * 1.17, vSurface.y, 19.7);
    vec3 pos = mix(worldCoord, doorCoord, isDoor);
    float scale = mix(mix(19.0, 15.5, isDoor), 21.0, isFloor);
    vec3 texel = floor(pos * 4.0) * 0.25;
    float g1 = noise3(texel / 2.1 + vec3(11.0, 17.0, 23.0));
    float g2 = noise3(texel / 0.85 + vec3(40.0, 53.0, 67.0));
    float grain = g1 * 0.52 + g2 * 0.48;
    vec3 jitter = vec3(
      noise3(pos / 3.8 + vec3(13.7, 29.1, 7.3)) - 0.5,
      noise3(pos / 3.8 + vec3(41.3, 7.9, 19.7)) - 0.5,
      noise3(pos / 3.8 + vec3(23.1, 51.7, 37.9)) - 0.5
    ) * 2.1 + vec3(g1 - 0.5, g2 - 0.5, (g1 - g2) * 0.7) * 0.9;
    vec3 pw = pos + jitter;
    float coarse = fbm3(pw / scale + vec3(21.0, 13.0, 37.0));
    float fineA = noise3(vec3(
      pw.x / (scale * 0.38) - pw.y / (scale * 0.51) + 9.0,
      pw.y / (scale * 0.38) + pw.z / (scale * 0.51) + 33.0,
      pw.z / (scale * 0.38) - pw.x / (scale * 0.51) + 57.0
    ));
    float fineB = 1.0 - abs(noise3(vec3(
      pw.x / (scale * 0.21) + pw.y / (scale * 0.29) + 51.0,
      pw.y / (scale * 0.21) - pw.z / (scale * 0.29) + 83.0,
      pw.z / (scale * 0.21) + pw.x / (scale * 0.29) + 19.0
    )) * 2.0 - 1.0);
    float drip = isVertical * (
      noise3(vec3(pw.x * 0.48 + 7.1, pw.y * 0.085 + 19.3, pw.z * 0.48 + 31.7)) * 0.58 +
      noise3(vec3(pw.x * 1.05 + 43.7, pw.y * 0.14 + 61.9, pw.z * 1.05 + 13.5)) * 0.42
    );
    float spots = mix(
      coarse * 0.40 + fineA * 0.30 + fineB * 0.18 + grain * 0.12,
      coarse * 0.36 + fineA * 0.27 + fineB * 0.16 + drip * 0.10 + grain * 0.11,
      isVertical
    );
    if (spots > 0.48) {
      float thresh = mix(mix(0.62, 0.60, isDoor), 0.60, isFloor);
      float patchGate = smoothstep(thresh - 0.06, thresh + 0.03, spots);
      vec3 seam32 = abs(fract((pos + jitter * 0.3) / 32.0) - 0.5);
      vec3 seam64 = abs(fract((pos + jitter * 0.2) / 64.0) - 0.5);
      float seamMask = smoothstep(0.42, 0.76, fineA * 0.58 + grain * 0.42);
      float nearSeam = mix(
        smoothstep(0.45, 0.5, max(seam64.x, seam64.z)) * 0.45,
        smoothstep(0.44, 0.5, max(seam32.x, seam32.z)) * 0.40 + smoothstep(0.45, 0.5, max(seam64.x, seam64.z)) * 0.60,
        isFloor
      ) * seamMask;
      float wallBand = isVertical * (1.0 - smoothstep(0.0, 5.5, max(vHeight, 0.0))) * 0.16 * seamMask * smoothstep(0.45, 0.80, drip);
      float area = smoothstep(thresh, thresh + 0.10, spots + crevice * 0.04 * patchGate - ridge * 0.04);
      area = clamp(area + (nearSeam * 0.16 + wallBand + crevice * 0.08) * patchGate, 0.0, 1.0);
      float near = 1.0 - smoothstep(220.0, 640.0, vDepth);
      if (near > 0.01 && area > 0.08) {
        float gShift = noise3((texel + vec3(0.25, -0.25, 0.25)) / 1.15 + vec3(40.0, 53.0, 67.0));
        bump = (g2 - gShift) * near;
      }
      float edgeBreak = smoothstep(0.26, 0.74, grain * 0.58 + fineB * 0.42);
      float breakup = mix(0.62 * edgeBreak, (0.20 + grain * 0.94 + crevice * 0.18 - ridge * 0.16) * (0.40 + 0.60 * edgeBreak), near);
      amount = clamp(area * breakup * 1.22 * (1.0 - protect), 0.0, 1.0);
      stain = smoothstep(0.08, 0.30, amount * 0.75 + area * edgeBreak * 0.25) * (1.0 - protect);
      flake = smoothstep(0.65, 0.90, grain) * smoothstep(0.48, 0.82, amount) * near;
      pit = smoothstep(0.39, 0.15, grain) * smoothstep(0.67, 0.93, amount + crevice * 0.21) * near;
    }
  }

  if (stain > 0.01) {
    vec3 steelDetail = steel - STEEL;
    vec3 stainedSteel = clamp(mix(STEEL, RUST_STAIN, 0.56) + steelDetail * 0.84, 0.0, 1.0);
    color = mix(steel, stainedSteel, stain * 0.28);
    if (amount > 0.14) {
      float tideRing = isFloor * smoothstep(0.16, 0.31, amount) * (1.0 - smoothstep(0.31, 0.50, amount));
      vec3 oxide = mix(RUST_DARK, RUST, smoothstep(0.22, 0.62, amount));
      oxide = mix(oxide, RUST_BRIGHT, smoothstep(0.58, 0.90, amount));
      oxide = mix(oxide, RUST_OCHRE, flake * 0.65);
      oxide = mix(oxide, RUST_PIT, clamp(pit * 0.78 + tideRing * 0.29, 0.0, 1.0));
      float relief = bump * (0.08 + 0.07 * amount);
      float keepSteel = mix(0.75, 0.27, smoothstep(0.20, 0.88, amount));
      vec3 corroded = clamp(oxide + steelDetail * keepSteel + vec3(1.0, 0.58, 0.28) * relief, 0.0, 1.0);
      float rustBlend = smoothstep(0.14, 0.38, amount) * clamp(0.34 + amount * 0.62 + tideRing * 0.14, 0.0, 1.0);
      color = mix(color, corroded, rustBlend);
    }
  }
  color *= uMaterialDiffuse * surfaceLight(vWorldPos, lit);
  if (uHasFog == 1) {
    float fade = clamp((vDepth - uFogNear) / (uFogFar - uFogNear), 0.0, 1.0);
    color = mix(color, uFogColor, fade);
  }
  gl_FragColor = vec4(color, 0.5);
}

vertex:
attribute vec3 aVertexPosition;
attribute vec2 aTextureCoord;
uniform mat4 uModelMatrix;
uniform mat4 uViewMatrix;
uniform mat4 uProjectionMatrix;
varying float vDepth;
varying vec3 vWorldPos;
varying vec2 vFixtureCenter;

void main(void) {
  vec4 world = uModelMatrix * vec4(aVertexPosition, 1.0);
  vec4 v = uViewMatrix * world;
  vDepth = -v.z;
  vWorldPos = world.xyz;
  vFixtureCenter = aTextureCoord;
  gl_Position = uProjectionMatrix * v;
}

fragment:
precision mediump float;
uniform vec3 uMaterialDiffuse;
uniform float uTime;
uniform int uHasFog;
uniform vec3 uFogColor;
uniform float uFogNear;
uniform float uFogFar;
varying float vDepth;
varying vec3 vWorldPos;
varying vec2 vFixtureCenter;

void main(void) {
  if (uHasFog == 1 && vDepth >= uFogFar)
    discard;
  float t = clamp((62.6 - vWorldPos.y) / 52.6, 0.0, 1.0);
  float topSoft = smoothstep(0.0, 0.06, t);
  float vFade = topSoft * (1.0 - t) * (1.0 - t) * (1.0 - t * 0.45);

  vec2 rel = vWorldPos.xz - vFixtureCenter;
  vec2 span = mix(vec2(22.0, 6.0), vec2(38.0, 20.0), t);
  vec2 q = rel / span;
  float xFade = 1.0 - smoothstep(0.12, 1.0, abs(q.x));
  float zFade = 1.0 - smoothstep(0.05, 1.0, abs(q.y));
  float hFade = xFade * xFade * zFade;

  // four soft fanned shafts matching the four louver bays of the ceiling fixture, diffusing as they descend
  float bay = 0.5 + 0.5 * cos(q.x * 12.56637);
  float shafts = mix(0.52 + 0.48 * bay * bay, 1.0, t * 0.72);

  float seed = fract(sin(dot(vFixtureCenter, vec2(12.9898, 78.233))) * 43758.5453);
  float hum = 1.0;
  if (seed < 0.2) {
    float wave = sin(uTime * 19.0 + seed * 31.4) * sin(uTime * 43.0 + seed * 53.4);
    hum = wave < -0.68 ? 0.64 : 0.96 + 0.04 * wave;
  }

  float nearFade = smoothstep(10.0, 34.0, vDepth);
  float fogFade = uHasFog == 1 ? 1.0 - clamp((vDepth - uFogNear) / (uFogFar - uFogNear), 0.0, 1.0) : 1.0;
  float alpha = vFade * hFade * shafts * hum * nearFade * fogFade * 0.075;
  if (alpha <= 0.001)
    discard;
  gl_FragColor = vec4(uMaterialDiffuse * alpha, 0.0);
}
